var n=`0278-begova-corba`;var t=`world-0278`;var a=`BA`;var o=`southern-europe`;var s=4;var r=73;var l={en:`Begova Čorba`,ua:`Бегова чорба`};var g={en:`A traditional Bosnia and Herzegovina dish made with chicken thigh, carrot, yellow onion, okra. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Боснія і Герцеговина. Основні інгредієнти: куряче стегно, морква, жовта цибуля, бамія. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var m=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 60 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 60 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:60,i:[[`chicken-thigh`,500,`g`],[`water`,1200,`ml`],[`carrot`,150,`g`],[`yellow-onion`,140,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`okra`,280,`g`],[`egg-yolk`,2,`pcs`],[`sour-cream`,150,`g`],[`lemon-juice`,25,`ml`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:4,i:[[`parsley`,18,`g`],[`table-salt`,null,`to_taste`]]}];var d={slug:n,id:t,country:`BA`,region:o,servings:4,minutes:73,title:l,text:g,steps:m};export{a as country,d as default,t as id,r as minutes,o as region,s as servings,n as slug,m as steps,g as text,l as title};